package dev.studyforge.banking.application; import dev.studyforge.banking.domain.*; import java.time.*; import java.util.*; public final class TransactionFactory{private final TimeProvider clock;private final TransactionIdProvider ids;public TransactionFactory(TimeProvider c,TransactionIdProvider i){clock=c;ids=i;}public Transaction deposit(AccountId to,Money a){return make(TransactionType.DEPOSIT,null,to,a,Money.zero(a.currency()));}public Transaction withdrawal(AccountId from,Money a,Money f){return make(TransactionType.WITHDRAWAL,from,null,a,f);}public Transaction transfer(AccountId from,AccountId to,Money a,Money f){return make(TransactionType.TRANSFER,from,to,a,f);}private Transaction make(TransactionType t,AccountId s,AccountId d,Money a,Money f){return new Transaction(ids.nextId(),t,s,d,a,f,clock.now());}}
